  });

  it("averages the middle pair on an even count", () => {
    const c = candidate({
      episodes: [episode({ travel_time_s: 10 }), episode({ travel_time_s: 20 })],
    });
    expect(medianTravelTime(c)).toBe(15);
  });

  it("counts only the failures, commonest first", () => {
    const c = candidate({
      episodes: [
