const asPercent = (value: number) => `${(value * 100).toFixed(1)} %`;
const asMs = (value: number) => `${value.toFixed(2)} ms`;
const asSeconds = (value: number) => `${value.toFixed(1)} s`;
const asMetres = (value: number) => `${value.toFixed(3)} m`;
